import { securityHeaders } from '../src/utils/security.js';

// Pages _headers applies to static assets, not responses generated by Functions.
export async function onRequest(context) {
  const response = await context.next();
  let values;
  try {
    values = securityHeaders(context.env);
  } catch {
    // Do not break the sitemap or article response on an invalid runtime setting.
    // Use the known production API origin and retain the configured CSP mode.
    console.warn('Invalid runtime API origin for CSP; using the production default');
    values = securityHeaders({ VITE_CSP_ENFORCE: context.env.VITE_CSP_ENFORCE });
  }
  const headers = new Headers(response.headers);
  headers.delete('Content-Security-Policy');
  headers.delete('Content-Security-Policy-Report-Only');
  for (const [name,value] of Object.entries(values)) headers.set(name,value);
  return new Response(response.body,{status:response.status,statusText:response.statusText,headers});
}
